<source id="1" url="https://chat.codercops.com/widget/react/" title="React" section="Quick Start">
React > Quick Start

In Next.js (App Router), root layouts (`app/layout.tsx`) are server components by default so they can export `metadata`. Define a small client component to hold your interactive callbacks:

```tsx
// app/chat.tsx
'use client';

import { ChatCops } from '@chatcops/react';

export function Chat() {
  return (
    <ChatCops
      apiUrl="/api/chat"
      branding={{ name: 'Acme' }}
      onLeadCaptured={(lead) => console.log('Lead captured:', lead)}
    />
  );
}
```

Then render `` from your root layout:

```tsx
// app/layout.tsx
import type { Metadata } from 'next';
import { Chat } from './chat';

export const metadata: Metadata = {
  title: 'My App',
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>
        {children}
        <Chat />
      </body>
    </html>
  );
}
```

If you do not need function or event props, `` can also be placed directly in a server component:

```tsx
import { ChatCops } from '@chatcops/react';

export default function Layout({ children }: { children: React.ReactNode }) {
  return (
    <div>
      {children}
      <ChatCops apiUrl="/api/chat" branding={{ name: 'Acme' }} />
    </div>
  );
}
```

Trigger actions anywhere in your application using `useChatCops()`:

```tsx
'use client';

import { useChatCops } from '@chatcops/react';

export function AskProductButton({ productName }: { productName: string }) {
  const chat = useChatCops();

  return (
    <button onClick={() => chat.send(`Is ${productName} in stock?`)}>
      Ask about this product
    </button>
  );
}
```
</source>
